const canvas=document.querySelector('#weave');
if(canvas){const ctx=canvas.getContext('2d');let w,h,t=0,frame,paused=matchMedia('(prefers-reduced-motion: reduce)').matches;function resize(){w=canvas.clientWidth;h=canvas.clientHeight;const d=Math.min(devicePixelRatio||1,2);canvas.width=w*d;canvas.height=h*d;ctx.setTransform(d,0,0,d,0,0)}function draw(){ctx.clearRect(0,0,w,h);ctx.save();ctx.translate(w*.77,h*.49);ctx.rotate(-.38);const radius=Math.min(w*.28,320);for(let j=0;j<64;j++){let a=j/64*Math.PI*2;ctx.beginPath();for(let i=0;i<=100;i++){let b=i/100*Math.PI*2;let twist=b*2+t*.2;let r=radius+Math.cos(twist+a)*radius*.32;let x=Math.cos(b)*r,y=Math.sin(b)*r*.76+Math.sin(twist+a)*radius*.34;if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y)}ctx.strokeStyle=j%9===0?'rgba(215,255,100,.64)':`rgba(210,216,187,${.12+.18*(Math.sin(a+t)+1)/2})`;ctx.lineWidth=j%9===0?1.6:.8;ctx.stroke()}ctx.restore();if(!paused){t+=.012;frame=requestAnimationFrame(draw)}}resize();draw();addEventListener('resize',()=>{resize();if(paused)draw()});document.querySelector('#motion').addEventListener('click',e=>{paused=!paused;e.target.textContent=paused?'Play motion ↻':'Pause motion Ⅱ';cancelAnimationFrame(frame);draw()});document.querySelector('#motion').textContent=paused?'Play motion ↻':'Pause motion Ⅱ';document.addEventListener('visibilitychange',()=>{cancelAnimationFrame(frame);if(!document.hidden)draw()})}
const recommendations=[['DESIGN & PRINT','Make your first impression match your ambition.','Start with a consistent visual identity, a clear offer, and collateral that gives prospects a reason to act. Bring your brochure or current brand assets to our conversation.'],['SEM · SEO · SMM','Turn visibility into a path to enquiry.','Start by checking search intent, campaign targeting, and the page visitors reach. Agree on a qualified-lead definition before spending more on traffic.'],['WEBSITES & E-COMMERCE','Find the friction between interest and action.','Review your mobile experience, product information, enquiry form, and checkout. Prioritise the obstacle closest to the sale before adding more features.'],['WEBSITE & EMAIL HOSTING','Build trust on a dependable foundation.','Review availability, backups, domain ownership, and email authentication. Clarify what is included in support and recovery before migrating.']];
document.querySelectorAll('.choice').forEach((b,i)=>b.addEventListener('click',()=>{document.querySelectorAll('.choice').forEach(x=>x.setAttribute('aria-pressed','false'));b.setAttribute('aria-pressed','true');let r=recommendations[i];document.querySelector('#result').innerHTML=`<small>${r[0]}</small><h3>${r[1]}</h3><p>${r[2]}</p><a class="text-link" href="/roadshow/?interest=${i}#brief">Build my conversation brief <svg class="arrow-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M5 19 19 5M5 5h14v14"/></svg></a>`}));
const form=document.querySelector('#leadform');if(form){let interest=new URLSearchParams(location.search).get('interest');if(interest!==null&&/^[0-3]$/.test(interest))form.elements.service.selectedIndex=Number(interest)+1;form.addEventListener('submit',e=>{e.preventDefault();const d=Object.fromEntries(new FormData(form));const text=`HABI DIGITAL GROUP — ROADSHOW CONVERSATION BRIEF\nCreated: ${new Date().toLocaleDateString('en-PH')}\n\nCompany: ${d.company}\nContact: ${d.name}\nEmail or phone: ${d.contact}\nWebsite: ${d.website||'Not provided'}\nService: ${d.service}\nTimeline: ${d.timeline}\nMain challenge: ${d.challenge}\nNext step: ${d.next||'Discuss with Habi'}\n\nSaved on this device only. This brief has not been sent to Habi. Share it directly with your Habi representative.\n`;const url=URL.createObjectURL(new Blob([text],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download='habi-conversation-brief.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#formstatus').textContent='Your brief is ready to download. Nothing has been sent. Share the file with your Habi representative.'});form.addEventListener('reset',()=>{document.querySelector('#formstatus').textContent=''})}
const enquiryForm=document.querySelector('#enquiryform');
if(enquiryForm){
 const send=enquiryForm.querySelector('button[type="submit"]');const notice=document.querySelector('#enquiry-status');
 enquiryForm.addEventListener('submit',async event=>{
  event.preventDefault();if(send.disabled||!enquiryForm.reportValidity())return;
  if(enquiryForm.elements._honey.value){notice.textContent='Unable to submit. Please email Habi directly.';return;}
  send.disabled=true;send.textContent='Sending…';notice.classList.remove('error');notice.textContent='Submitting your enquiry securely…';
  const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),25000);
  try{
   const data=Object.fromEntries(new FormData(enquiryForm));delete data._next;
   const response=await fetch('https://formsubmit.co/ajax/amparooskar@gmail.com',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify(data),signal:controller.signal});
   const result=await response.json();
   if(/activat|confirm.*email/i.test(result.message||'')){notice.classList.add('error');notice.textContent='Email delivery is awaiting recipient activation. Please email oskaramparo@habi-digitalgroup.com directly for now. Your details remain here so you can copy them.';}
   else{if(!response.ok||!(result.success===true||result.success==='true'))throw new Error('provider');enquiryForm.reset();notice.textContent='Your enquiry was accepted for delivery. Thank you for contacting Habi. We’ll use your details to follow up.';}
  }catch(error){notice.classList.add('error');notice.textContent=error.name==='AbortError'?'The request timed out, so delivery is unconfirmed. Your details are still here. Please email oskaramparo@habi-digitalgroup.com if you need assistance.':'We couldn’t confirm submission. Your details are still here. Please try again or email oskaramparo@habi-digitalgroup.com.';}
  finally{clearTimeout(timer);send.disabled=false;send.innerHTML='Send my enquiry <span><svg class="arrow-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M5 19 19 5M5 5h14v14"/></svg></span>';}
 });
}
